(function(){
  function start(host, ctx){
    var DINOS = [
      {
        id:'stego', name:'Stegosaurus', diet:'plant',
        img:'data:image/jpeg;base64,',
        clue:'Look at its mouth. Stegosaurus has a small beak for snipping leaves, not sharp teeth for biting animals.',
        fact:'Stegosaurus had bony plates along its back and sharp spikes on its tail. Scientists think the plates may have helped it warm up, cool down, or look bigger to enemies.'
      },
      {
        id:'trike', name:'Triceratops', diet:'plant',
        img:'data:image/jpeg;base64,',
        clue:'Look at its mouth. Triceratops has a beak like a parrot for snipping tough plants.',
        fact:'Triceratops used its three horns and its big bony frill to protect itself from predators like T. rex.'
      },
      {
        id:'allo', name:'Allosaurus', diet:'meat',
        img:'data:image/jpeg;base64,',
        clue:'Look at its jaws. Allosaurus has long, curved, pointy teeth built for grabbing other animals.',
        fact:'Allosaurus was one of the fiercest hunters of its time, with dozens of sharp, curved teeth for tearing meat.'
      },
      {
        id:'brach', name:'Brachiosaurus', diet:'plant',
        img:'data:image/jpeg;base64,',
        clue:'Look at its neck. That long neck was built for reaching leaves at the top of trees, not for chasing prey.',
        fact:'Brachiosaurus had a very long neck that let it reach leaves at the top of tall trees, like a natural ladder.'
      }
    ];

    var TOTAL_TILES = 15;
    var CLEAR_NEEDED = 10;
    var STAR_NEEDED = 6;
    var TOTAL_QUESTIONS = DINOS.length * 2;

    var siteIndex = 0;
    var order = [];
    var firstTryCorrect = 0;
    var clearedCount = 0;

    function shuffle(arr){
      var a = arr.slice();
      for (var i = a.length - 1; i > 0; i--){
        var j = Math.floor(Math.random() * (i + 1));
        var t = a[i]; a[i] = a[j]; a[j] = t;
      }
      return a;
    }

    function shell(innerHtml){
      host.innerHTML =
        '<div class="row" style="justify-content:flex-end;margin-bottom:6px;">' +
          '<button class="btn ghost sm" id="mapBtn">\u2190 Map</button>' +
        '</div>' +
        innerHtml;
      var mapBtn = host.querySelector('#mapBtn');
      if (mapBtn) mapBtn.addEventListener('pointerup', function(){ ctx.close(); });
    }

    function renderIntro(){
      shell(
        '<div class="center">' +
          '<p class="sub">Clover found an old dig site at Union Station\'s Science City! Real dinosaur bones are buried under the dirt. Brush away the tiles, then help Clover figure out which dinosaur it is, and whether it ate plants or meat.</p>' +
          '<button class="btn green mt" id="startBtn">Start digging</button>' +
        '</div>'
      );
      host.querySelector('#startBtn').addEventListener('pointerup', function(){
        order = shuffle([0,1,2,3]);
        siteIndex = 0;
        firstTryCorrect = 0;
        renderDig();
      });
    }

    function renderDig(){
      var dino = DINOS[order[siteIndex]];
      clearedCount = 0;
      shell(
        '<p class="sub center">Dig site ' + (siteIndex + 1) + ' of ' + DINOS.length + '</p>' +
        '<div id="digWrap" style="position:relative;max-width:420px;margin:8px auto;border-radius:12px;overflow:hidden;border:3px solid #b5651d;">' +
          '<img src="' + dino.img + '" style="display:block;width:100%;height:auto;background:#fff;" />' +
          '<div id="tileGrid" style="position:absolute;inset:0;display:grid;grid-template-columns:repeat(5,1fr);grid-template-rows:repeat(3,1fr);"></div>' +
        '</div>' +
        '<p class="sub center">Tap the dirt to brush it away.</p>'
      );

      var grid = host.querySelector('#tileGrid');
      var shades = ['#b6935f', '#a9835a', '#c1a06e'];
      for (var i = 0; i < TOTAL_TILES; i++){
        var tile = document.createElement('div');
        tile.style.background = shades[i % 3];
        tile.style.border = '1px solid rgba(0,0,0,.08)';
        tile.style.cursor = 'pointer';
        tile.style.transition = 'opacity .25s ease';
        tile.dataset.cleared = 'false';
        tile.addEventListener('pointerup', (function(t){
          return function(){
            if (t.dataset.cleared === 'true') return;
            t.dataset.cleared = 'true';
            t.style.opacity = '0';
            t.style.pointerEvents = 'none';
            clearedCount++;
            if (clearedCount >= CLEAR_NEEDED){
              renderMatch(dino);
            }
          };
        })(tile));
        grid.appendChild(tile);
      }
    }

    function renderMatch(dino){
      var options = shuffle(DINOS.map(function(d){ return d.name; }));
      shell(
        '<div class="center">' +
          '<img src="' + dino.img + '" style="max-width:280px;border-radius:10px;margin:0 auto 10px;display:block;" />' +
          '<p class="h3">You uncovered the fossil! Which dinosaur is this?</p>' +
          '<div id="matchOpts" class="row" style="flex-wrap:wrap;justify-content:center;gap:8px;"></div>' +
          '<p class="fb" id="matchFb"></p>' +
        '</div>'
      );
      var firstAttempt = true;
      var wrap = host.querySelector('#matchOpts');
      options.forEach(function(name){
        var b = document.createElement('button');
        b.className = 'q-opt';
        b.textContent = name;
        b.addEventListener('pointerup', function(){
          var fb = host.querySelector('#matchFb');
          if (name === dino.name){
            if (firstAttempt) firstTryCorrect++;
            fb.className = 'fb ok';
            fb.textContent = 'Yes! This is a ' + dino.name + '.';
            if (ctx.toast) ctx.toast('Nice find!');
            setTimeout(function(){ renderCategorize(dino); }, 800);
          } else {
            firstAttempt = false;
            fb.className = 'fb no';
            fb.textContent = 'Not quite, look again and try another.';
          }
        });
        wrap.appendChild(b);
      });
    }

    function renderCategorize(dino){
      shell(
        '<div class="center">' +
          '<img src="' + dino.img + '" style="max-width:260px;border-radius:10px;margin:0 auto 10px;display:block;" />' +
          '<p class="h3">Was the ' + dino.name + ' a meat eater or a plant eater?</p>' +
          '<p class="sub">' + dino.clue + '</p>' +
          '<div class="row" style="justify-content:center;gap:10px;">' +
            '<button class="q-opt" id="optMeat">Meat eater</button>' +
            '<button class="q-opt" id="optPlant">Plant eater</button>' +
          '</div>' +
          '<p class="fb" id="catFb"></p>' +
        '</div>'
      );
      var firstAttempt = true;
      function answer(pick){
        var fb = host.querySelector('#catFb');
        if (pick === dino.diet){
          if (firstAttempt) firstTryCorrect++;
          fb.className = 'fb ok';
          fb.textContent = dino.fact;
          host.querySelector('#optMeat').disabled = true;
          host.querySelector('#optPlant').disabled = true;
          var nextBtn = document.createElement('button');
          nextBtn.className = 'btn teal mt';
          nextBtn.textContent = (siteIndex < DINOS.length - 1) ? 'Next dig site' : 'See results';
          nextBtn.addEventListener('pointerup', function(){
            siteIndex++;
            if (siteIndex >= DINOS.length){ renderSummary(); } else { renderDig(); }
          });
          host.querySelector('.center').appendChild(nextBtn);
        } else {
          firstAttempt = false;
          fb.className = 'fb no';
          fb.textContent = 'Take another look and try again.';
        }
      }
      host.querySelector('#optMeat').addEventListener('pointerup', function(){ answer('meat'); });
      host.querySelector('#optPlant').addEventListener('pointerup', function(){ answer('plant'); });
    }

    function renderSummary(){
      var earnedStar = (firstTryCorrect >= STAR_NEEDED) && !ctx.state.unionstationStarEarned;
      ctx.state.unionstationDone = true;
      shell(
        '<div class="center">' +
          '<img src="' + ctx.clover.cele + '" style="width:120px;margin:0 auto 10px;display:block;" />' +
          '<p class="h2">Great digging!</p>' +
          '<p class="sub">You helped Clover identify all ' + DINOS.length + ' fossils at Science City.</p>' +
          '<button class="btn green mt" id="doneBtn">Back to map</button>' +
        '</div>'
      );
      ctx.award({ coins: 12, star: earnedStar });
      if (earnedStar){
        ctx.state.unionstationStarEarned = true;
        if (ctx.confetti) ctx.confetti();
      }
      host.querySelector('#doneBtn').addEventListener('pointerup', function(){ ctx.close(); });
    }

    renderIntro();
  }

  window.Stops.register('5C', { name:'Union Station', start });
})();
